def _build_component_06():
    def solve(data):
        packages = data["packages"]
        roots = data["roots"]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        names = sorted(packages, reverse=True)
        candidates = {}
        for name in names:
            rows = packages[name]
            candidates[name] = {row["version"]: row for row in rows}

        best_vector = None
        best = None
        # Enumerate each package as absent or at one of its available versions.
        import itertools
        choices = [[None] + sorted(candidates[name]) for name in names]
        for values in itertools.product(*choices):
            install = {name: ver for name, ver in zip(names, values) if ver is not None}
            valid = True
            for name, (low, high) in roots.items():
                ver = install.get(name)
                if ver is None or not low <= ver <= high:
                    valid = False
                    break
            if not valid:
                continue
            for name, ver in install.items():
                if ver in blocked.get(name, []) or (name in pins and pins[name] != ver):
                    valid = False
                    break
            if not valid:
                continue

            edges = {}
            for name, ver in install.items():
                edges[name] = []
                row = candidates[name][ver]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    dv = install.get(target)
                    if dv is None or not dep["min"] <= dv <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if reachable != set(install):
                continue

            done, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                done.add(name)
                return True
            if not all(visit(name) for name in install):
                continue

            vector = tuple(install.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector, best = vector, install
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _build_component_07():
    from itertools import combinations
    import heapq

    def feasible(selected, data):
        ids = {j["id"] for j in selected}
        if not set(data.get("mandatory", [])).issubset(ids):
            return False
        counts = {}
        for j in selected:
            counts[j["group"]] = counts.get(j["group"], 0) + 1
        for group, (low, high) in data.get("quotas", {}).items():
            if not low <= counts.get(group, 0) <= high:
                return False
        active = []
        for job in sorted(selected, key=lambda j: (j["start"], j["end"], j["id"])):
            while active and active[0] <= job["start"]:
                heapq.heappop(active)
            heapq.heappush(active, job["end"])
            if len(active) > 2:
                return False
        return True

    def solve(data):
        jobs = [j for j in data["jobs"] if j["id"] not in data.get("blocked", [])]
        best_value = None
        best_ids = None
        for subset in combinations(jobs, data["k"]):
            if not feasible(subset, data):
                continue
            value = sum(j["value"] for j in subset)
            ids = sorted(j["id"] for j in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source = data["source"]
        mask = bit.get(source, 0)
        start = data["start"]
        initial = (source, mask, data["coupons"])
        dist = {initial: start}
        queue = [(start, source, mask, data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, remaining - 1))
                for duration, left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    newmask = mask | bit.get(nxt, 0)
                    ns = (nxt, newmask, left)
                    if arrival < dist.get(ns, float("inf")):
                        dist[ns] = arrival
                        heapq.heappush(queue, (arrival, nxt, newmask, left))
        return {"arrival": None}
    return solve


