def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << index for index, node in enumerate(required)}
        full_mask = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        start = data["start"]
        initial_mask = bit_for.get(source, 0)
        initial = (source, initial_mask, data["coupons"])
        distances = {initial: start}
        queue = [(start, source, initial_mask, data["coupons"])]

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full_mask:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [(edge["duration"], remaining)]
                if remaining:
                    discounted = max(1, edge["duration"] - edge.get("discount", 0))
                    durations.append((discounted, remaining - 1))
                for duration, coupons_left in durations:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit_for.get(next_node, 0)
                    next_state = (next_node, next_mask, coupons_left)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, coupons_left))
        return {"arrival": None}
    return solve


